150→// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
151→// on /full/current while preserving other checkpoints' transcripts in the tree.
152→func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
153→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
154→	if err := s.ensureRef(refName); err != nil {
155→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
156→	}
157→
158→	parentHash, rootTreeHash, err := s.getRefState(refName)
159→	if err != nil {
160→		return err
161→	}
162→
163→	basePath := opts.CheckpointID.Path() + "/"
164→	checkpointPath := opts.CheckpointID.Path()
165→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
166→
167→	// Read existing entries and replace transcript for this checkpoint only
168→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
169→	if err != nil {
170→		return err
171→	}
172→
173→	// Clear existing transcript entries at this session path before writing new ones
174→	for key := range entries {
175→		if strings.HasPrefix(key, sessionPath) {
176→			delete(entries, key)
177→		}
178→	}
179→
180→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
181→	if err != nil {
182→		return err
183→	}
184→
185→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
186→		return err
187→	}
188→
189→	// Splice into existing root tree (preserves other checkpoints' transcripts)
190→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
191→	if err != nil {
192→		return err
193→	}
194→
195→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
196→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
197→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
198→}
