355→// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
356→func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
357→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
358→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
359→	if err != nil {
360→		return err
361→	}
362→	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
363→		Name: sessionPath + paths.ContentHashFileName,
364→		Mode: filemode.Regular,
365→		Hash: hashBlob,
366→	}
367→	return nil
368→}
