370→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
371→// Transcripts accumulate across checkpoints — each write splices into the existing
372→// tree. When the ref reaches capacity, generation rotation (future work) archives
373→// the current ref and starts a fresh one.
374→//
375→// sessionIndex is the session slot (0-based), determined by the caller to stay
376→// consistent with the /main ref's session numbering.
377→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
378→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
379→	transcript := opts.Transcript
380→	if len(transcript) == 0 && opts.TranscriptPath != "" {
381→		var readErr error
382→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
383→		if readErr != nil {
384→			transcript = nil
385→		}
386→	}
387→	if len(transcript) == 0 {
388→		return nil // No transcript to write
389→	}
390→
391→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
392→	if err := s.ensureRef(refName); err != nil {
393→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
394→	}
395→
396→	parentHash, rootTreeHash, err := s.getRefState(refName)
397→	if err != nil {
398→		return err
399→	}
400→
401→	basePath := opts.CheckpointID.Path() + "/"
402→	checkpointPath := opts.CheckpointID.Path()
403→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
404→
405→	// Read existing entries at this checkpoint's shard path (accumulate, don't replace)
406→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
407→	if err != nil {
408→		return err
409→	}
410→
411→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
412→	if err != nil {
413→		return err
414→	}
415→
416→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
417→		return err
418→	}
419→
420→	// Splice into existing root tree (preserves other checkpoints' transcripts)
421→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
422→	if err != nil {
423→		return err
424→	}
425→
426→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
427→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
428→}
