430→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
431→// Returns the redacted transcript bytes so the caller can compute the content hash.
432→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
433→	// Redact secrets before chunking
434→	redacted, err := redact.JSONLBytes(transcript)
435→	if err != nil {
436→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
437→	}
438→
439→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
440→	if err != nil {
441→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
442→	}
443→
444→	for i, chunk := range chunks {
445→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
446→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
447→		if err != nil {
448→			return nil, err
449→		}
450→		entries[chunkPath] = object.TreeEntry{
451→			Name: chunkPath,
452→			Mode: filemode.Regular,
453→			Hash: blobHash,
454→		}
455→	}
456→
457→	return redacted, nil
458→}
