460→// validateWriteOpts validates identifiers in WriteCommittedOptions.
461→func validateWriteOpts(opts WriteCommittedOptions) error {
462→	if opts.CheckpointID.IsEmpty() {
463→		return errors.New("invalid checkpoint options: checkpoint ID is required")
464→	}
465→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
466→		return fmt.Errorf("invalid checkpoint options: %w", err)
467→	}
468→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
469→		return fmt.Errorf("invalid checkpoint options: %w", err)
470→	}
471→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
472→		return fmt.Errorf("invalid checkpoint options: %w", err)
473→	}
474→	return nil
475→}
